import string

alphabet = [chr(i) for i in range(ord('a'), ord('z') + 1)]
alphabetnums = {chr(i): str(j + 1) for j, i in enumerate(range(ord('a'), ord('z') + 1))}

def AlphaNum_NumAlpha(s):
    result = []
    i = 0
    while i < len(s):
        if s[i].isalpha():
            result.append(alphabetnums[s[i]])
            i += 1
        elif s[i].isdigit():
            num_str = ""
            while i < len(s) and s[i].isdigit():
                num_str += s[i]
                i += 1
            num = int(num_str)
            result.append(alphabet[num - 1])
        else:
            result.append(s[i])
            i += 1
    return "".join(result)
